import numpy as np

def companion(a, b, c):
    """The matrix A of x' = A x for a y'' + b y' + c y = 0, x = (y, y')."""
    return np.array([[0.0, 1.0], [-c / a, -b / a]])

def solve_linear_system(A, x0, t):
    """x(t) for x' = A x, x(0) = x0, A diagonalisable; the real part."""
    vals, V = np.linalg.eig(np.asarray(A, dtype=float))
    c = np.linalg.solve(V, np.asarray(x0, dtype=float))
    return np.real(V @ (c * np.exp(vals * t)))
